settings.custom_liquid:
{% assign booking_date = product.metafields.custom.event_date_and_time %}

{% if booking_date != blank %}
  {% assign now_timestamp = 'now' | date: '%s' | plus: 0 %}
  {% assign booking_timestamp = booking_date | date: '%s' | plus: 0 %}
  {% assign diff_seconds = booking_timestamp | minus: now_timestamp %}
{% endif %}

<div class="booking-wrapper">

  <!-- ✅ FORM SHOW ONLY IF BOOKING OPEN -->
  {% if diff_seconds > 0 %}

    <!-- Date of Birth -->
    <div class="form-group">
      <label>Date of Birth</label>
      <input type="date"
        name="properties[Date of Birth]"
        form="{{ 'product-form-' | append: section.id }}"
        required>
    </div>

    <!-- Birth Time -->
    <div class="form-group">
      <label>Birth Time</label>
      <input type="time"
        name="properties[Birth Time]"
        form="{{ 'product-form-' | append: section.id }}"
        required>
    </div>

    <!-- Homam Date -->
    {% assign show_homam = product.metafields.custom.homam_date_picker %}
    {% if show_homam == true %}
      <div class="form-group">
        <label>Homam Date</label>
        <input type="date"
          name="properties[Homam Date]"
          form="{{ 'product-form-' | append: section.id }}"
          required>
      </div>
    {% endif %}

    <!-- Rasi -->
    <div class="form-group">
      <label>Rasi</label>
      <select name="properties[Rasi]"
        form="{{ 'product-form-' | append: section.id }}"
        required>
        <option value="" hidden selected>Please select</option>
        <option>Aries</option>
        <option>Taurus</option>
        <option>Gemini</option>
        <option>Cancer</option>
        <option>Leo</option>
        <option>Virgo</option>
        <option>Libra</option>
        <option>Scorpio</option>
        <option>Sagittarius</option>
        <option>Capricorn</option>
        <option>Aquarius</option>
        <option>Pisces</option>
      </select>
    </div>

    <!-- Nakshatra -->
    <div class="form-group">
      <label>Nakshatra</label>
      <select name="properties[Nakshatra]"
        form="{{ 'product-form-' | append: section.id }}"
        required>
        <option value="" hidden selected>Please select</option>
        <option>Ashwini</option>
        <option>Bharani</option>
        <option>Karthigai</option>
        <option>Rohini</option>
        <option>Mrigashirsha</option>
        <option>Arudra</option>
        <option>Punarvasu</option>
        <option>Pushya</option>
        <option>Ashlesha</option>
        <option>Magha</option>
        <option>Purva Phalguni</option>
        <option>Uttara Phalguni</option>
        <option>Hasta</option>
        <option>Chitra</option>
        <option>Swati</option>
        <option>Vishakha</option>
        <option>Anuradha</option>
        <option>Jyeshta</option>
        <option>Moola</option>
        <option>Purva Ashadha</option>
        <option>Uttara Ashadha</option>
        <option>Shravana</option>
        <option>Dhanishta</option>
        <option>Shatabhisha</option>
        <option>Purva Bhadrapada</option>
        <option>Uttara Bhadrapada</option>
        <option>Revati</option>
      </select>
    </div>

    <!-- Place -->
    <div class="form-group">
      <label>Place Of Birth</label>
      <input type="text"
        name="properties[Place Of Birth]"
        form="{{ 'product-form-' | append: section.id }}"
        placeholder="Enter place"
        required>
    </div>

    <!-- Comments -->
    <div class="form-group">
      <label>Comments</label>
      <textarea rows="4"
        name="properties[Comments]"
        form="{{ 'product-form-' | append: section.id }}"
        placeholder="Optional notes"></textarea>
    </div>

  {% endif %}

</div>

<style>

/* Form group */
.form-group {
  margin-bottom: 18px;
  display: flex;
  flex-direction: column;
}

/* Labels */
.form-group label {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 6px;
  color: rgb(var(--color-foreground));
}

/* Inputs */
.form-group input,
.form-group select,
.form-group textarea {
  padding: 12px;
  border-radius: 12px;
  border: 1px solid rgba(var(--color-foreground), 0.2);
  background: rgb(var(--color-background));
  color: rgb(var(--color-foreground));
  font-size: 14px;
  transition: all 0.3s ease;
}

/* Focus */
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: rgb(var(--color-button));
  box-shadow: 0 0 0 2px rgba(var(--color-button), 0.15);
  outline: none;
}

/* Placeholder */
.form-group input::placeholder,
.form-group textarea::placeholder {
  color: rgba(var(--color-foreground), 0.5);
}

/* Dropdown */
.form-group select {
  cursor: pointer;
}

/* Textarea */
textarea {
  resize: vertical;
  min-height: 100px;
}

/* Mobile */
@media (max-width: 600px) {
  .booking-wrapper {
    padding: 15px;
  }

  .form-group input,
  .form-group select,
  .form-group textarea {
    font-size: 13px;
    padding: 10px;
  }
}
</style>
